begin;
select no_plan();
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
update public.agency_memberships set role_key='developer' where user_id=auth.uid();
set local role authenticated;
select lives_ok($$select public.create_billing_draft('70000000-0000-0000-0000-00000000d101','30000000-0000-0000-0000-00000000000a',null,'invoice_like','2026-10-14','MXN','QA service',147.37,0)$$,'Developer creates an atomic draft and item under existing RLS');
select is((select subtotal_amount from public.billing_documents where id='70000000-0000-0000-0000-00000000d101'),147.37::numeric,'Authoritative subtotal is preserved');
select is((select sum(line_total) from public.billing_document_items where billing_document_id='70000000-0000-0000-0000-00000000d101'),147.37::numeric,'Document and concept totals match');
select lives_ok($$select public.create_billing_draft('70000000-0000-0000-0000-00000000d101','30000000-0000-0000-0000-00000000000a',null,'invoice_like','2026-10-14','MXN','QA service',147.37,0)$$,'An identical network retry returns the same draft');
select is((select count(*) from public.billing_document_items where billing_document_id='70000000-0000-0000-0000-00000000d101'),1::bigint,'Retry never duplicates concepts');
select throws_ok($$select public.create_billing_draft('70000000-0000-0000-0000-00000000d101','30000000-0000-0000-0000-00000000000a',null,'invoice_like','2026-10-14','MXN','Changed request',147.37,0)$$,'22023','billing_draft_retry_conflict','Same retry key cannot change financial intent');
select lives_ok($$select public.issue_billing_document('70000000-0000-0000-0000-00000000d101',gen_random_uuid())$$,'Existing issue command accepts the complete draft');
select throws_ok($$select public.create_billing_draft('70000000-0000-0000-0000-00000000d102','30000000-0000-0000-0000-00000000000a',null,'invoice_like','2026-10-14','MXN','',147.37,0)$$,'22023','invalid_billing_draft','Invalid concept fails the whole transaction');
select is((select count(*) from public.billing_documents where id='70000000-0000-0000-0000-00000000d102'),0::bigint,'Invalid input leaves no partial document');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000004',true);
set local role authenticated;
select throws_ok($$select public.create_billing_draft('70000000-0000-0000-0000-00000000d103','30000000-0000-0000-0000-00000000000a',null,'invoice_like','2026-10-14','MXN','Denied service',147.37,0)$$,'42501',null,'Contributor cannot use wrapper to obtain Billing rights');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000005',true);
set local role authenticated;
select throws_ok($$select public.create_billing_draft('70000000-0000-0000-0000-00000000d104','30000000-0000-0000-0000-00000000000a',null,'invoice_like','2026-10-14','MXN','Client service',147.37,0)$$,'42501',null,'Client cannot create internal financial drafts');
reset role;
select * from finish();
rollback;
